INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'barbell-bench-press'), 'de', 'Bankdrücken', 'Flachbankdrücken mit der Langhantel, die wichtigste horizontale Druckübung.', 'Flach hinlegen, etwas breiter als schulterbreit greifen, zur Brustmitte absenken und wieder hochdrücken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'incline-dumbbell-press'), 'de', 'Kurzhantel-Schrägbankdrücken', 'Schrägbankdrücken mit Fokus auf die obere Brust.', 'Bank auf 30 Grad stellen, Kurzhanteln hochdrücken, ohne die Ellbogen hart durchzustrecken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'cable-chest-fly'), 'de', 'Fliegende am Kabelzug', 'Isolation für die Brust mit konstanter Spannung am Kabelzug.', 'Ellbogen leicht gebeugt, Griffe vor dem Brustbein zusammenführen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'barbell-row'), 'de', 'Langhantelrudern', 'Vorgebeugtes Rudern für einen kräftigen mittleren Rücken.', 'Oberkörper auf etwa 45 Grad vorbeugen, Stange zu den unteren Rippen ziehen, Rücken neutral halten.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'seated-cable-row'), 'de', 'Rudern am Kabelzug', 'Horizontales Ziehen am Kabelzug.', 'Aufrecht sitzen, Griff zum Bauchnabel ziehen, kontrolliert zurückführen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'chest-supported-dumbbell-row'), 'de', 'Kurzhantelrudern mit Brustauflage', 'Rudervariante ohne Belastung des unteren Rückens.', 'Brust auf eine Schrägbank legen, Kurzhanteln zu den unteren Rippen ziehen, Schulterblätter zusammenziehen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'wide-grip-seated-cable-row'), 'de', 'Breites Rudern am Kabelzug', 'Horizontales Ziehen mit breitem Griff für oberen Rücken und hintere Schulter.', 'Breite Stange, mit abgespreizten Ellbogen zur unteren Brust ziehen, Schulterblätter zusammenziehen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'pull-up'), 'de', 'Klimmzug', 'Vertikales Ziehen mit dem eigenen Körpergewicht.', 'Im Obergriff hängen, Brust zur Stange ziehen, vollständig absenken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'lat-pulldown'), 'de', 'Latziehen', 'Vertikales Ziehen an der Maschine mit anpassbarem Gewicht.', 'Stange zur oberen Brust ziehen, Oberkörper fast aufrecht halten.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'straight-arm-pulldown'), 'de', 'Überzüge am Kabelzug', 'Lat-Isolation mit gestreckten Armen.', 'Arme gestreckt halten, Stange bis zu den Oberschenkeln nach unten ziehen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'barbell-shrug'), 'de', 'Langhantel-Shrugs', 'Shrugs für den oberen Trapezius.', 'Schultern gerade nach oben ziehen, kurz halten, kontrolliert absenken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'dumbbell-shrug'), 'de', 'Kurzhantel-Shrugs', 'Shrugs mit größerem Bewegungsumfang.', 'Kurzhanteln seitlich halten, Schultern anheben, ohne sie zu kreisen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'farmers-walk'), 'de', 'Farmers Walk', 'Tragen schwerer Gewichte für Trapezius, Unterarme und Rumpf.', 'Schwere Kurzhanteln über eine Strecke tragen, Rippen unten, Schultern stabil.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'overhead-barbell-press'), 'de', 'Langhantel-Überkopfdrücken', 'Stehendes Drücken über Kopf.', 'Stange über Kopf drücken, Kopf leicht zurücknehmen, über der Fußmitte durchstrecken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'seated-dumbbell-shoulder-press'), 'de', 'Kurzhantel-Schulterdrücken sitzend', 'Vertikales Drücken mit Rückenstütze.', 'Kurzhanteln von Schulterhöhe bis zur Streckung drücken, Ellbogen leicht vor dem Körper.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'dumbbell-front-raise'), 'de', 'Frontheben mit Kurzhanteln', 'Isolation für die vordere Schulter.', 'Kurzhanteln mit leicht gebeugten Ellbogen bis auf Augenhöhe heben.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'dumbbell-lateral-raise'), 'de', 'Seitheben mit Kurzhanteln', 'Klassische Isolation für die seitliche Schulter.', 'Bis auf Schulterhöhe heben, die Ellbogen führen, kein Schwung.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'cable-lateral-raise'), 'de', 'Seitheben am Kabelzug', 'Seitheben mit konstanter Spannung.', 'Kabel von der unteren Rolle hinter dem Körper, seitlich bis auf Schulterhöhe heben.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'upright-row'), 'de', 'Aufrechtes Rudern', 'Vertikales Ziehen für seitliche Schulter und Trapezius.', 'Schulterbreit greifen, zur unteren Brust ziehen, Ellbogen über den Handgelenken halten.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'face-pull'), 'de', 'Face Pull', 'Training für hintere Schulter und Außenrotatoren.', 'Seil auf Gesichtshöhe, zur Stirn ziehen, Ellbogen hoch.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'reverse-pec-deck'), 'de', 'Reverse Butterfly', 'Reverse Flys an der Maschine.', 'Brust gegen das Polster, Arme in einem weiten Bogen öffnen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'bent-over-dumbbell-reverse-fly'), 'de', 'Vorgebeugtes Seitheben', 'Reverse Flys mit freien Gewichten.', 'Oberkörper vorbeugen, Kurzhanteln mit leicht gebeugten Ellbogen seitlich heben.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'barbell-curl'), 'de', 'Langhantelcurl', 'Grundlegender Bizepscurl mit der Langhantel.', 'Ellbogen am Körper, hochcurlen, in etwa drei Sekunden absenken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'incline-dumbbell-curl'), 'de', 'Kurzhantelcurl auf der Schrägbank', 'Curl mit gedehnter Schulterposition.', 'Bank auf 45 Grad, Arme hängen lassen, curlen ohne die Ellbogen zu bewegen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'hammer-curl'), 'de', 'Hammercurl', 'Curl im neutralen Griff für Bizeps und Brachialis.', 'Neutraler Griff, hochcurlen, Handgelenke gerade halten.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'machine-preacher-curl'), 'de', 'Scottcurl an der Maschine', 'Bizepscurl mit auf einem Polster fixierten Oberarmen.', 'Oberarme flach auf dem Polster, hochcurlen, absenken bis die Arme fast gestreckt sind.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'close-grip-bench-press'), 'de', 'Enges Bankdrücken', 'Mehrgelenkige Druckübung für den Trizeps.', 'Schulterbreiter Griff, Ellbogen nah am Körper, bis zur Streckung drücken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'triceps-rope-pushdown'), 'de', 'Trizepsdrücken am Seil', 'Isolation für den Trizeps am Kabelzug.', 'Ellbogen seitlich fixiert, nach unten drücken und das Seil unten auseinanderziehen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'overhead-cable-triceps-extension'), 'de', 'Überkopf-Trizepsstrecken am Kabelzug', 'Trizepstraining in gedehnter Position.', 'Seil über Kopf, Ellbogen vollständig strecken, Oberarme ruhig halten.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'wrist-curl'), 'de', 'Handgelenkcurl', 'Training der Beuger im Unterarm.', 'Unterarme auf den Oberschenkeln, Handgelenke hochcurlen, voller Bewegungsumfang.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'reverse-wrist-curl'), 'de', 'Reverse Handgelenkcurl', 'Training der Strecker im Unterarm.', 'Obergriff, Handgelenke nach oben strecken, leichtes Gewicht verwenden.');
