INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'cable-woodchop'), 'de', 'Holzhacker am Kabelzug', 'Diagonale Rotation am Kabelzug.', 'Griff diagonal über den Körper ziehen, aus der Hüfte drehen.');
