INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'lying-leg-curl'), 'de', 'Beinbeuger liegend', 'Kniebeugung in Bauchlage.', 'Fersen zum Gesäß ziehen, Hüfte auf dem Polster lassen.');
