INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'cable-glute-kickback'), 'de', 'Glute Kickback am Kabelzug', 'Isolation der Hüftstreckung am Kabelzug.', 'Fußschlaufe am Kabel, Hüfte nach hinten strecken, kein Hohlkreuz.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'standing-calf-raise'), 'de', 'Wadenheben stehend', 'Wadenheben mit gestreckten Knien.', 'Unten voll dehnen, auf die Zehen hochdrücken, oben kurz halten.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'seated-calf-raise'), 'de', 'Wadenheben sitzend', 'Wadenheben mit gebeugten Knien für den Soleus.', 'Polster auf den Oberschenkeln, auf die Zehen hochdrücken, langsam absenken.');
