INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'hip-adduction-machine'), 'de', 'Adduktorenmaschine', 'Maschinentraining für die Adduktoren.', 'Beine gegen die Polster zusammendrücken, kontrolliert zurückführen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'cable-hip-adduction'), 'de', 'Adduktion am Kabelzug', 'Einbeinige Adduktion am Kabelzug.', 'Fußschlaufe am Bein, das näher am Turm steht, über die Körpermitte ziehen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'copenhagen-plank'), 'de', 'Copenhagen Plank', 'Isometrisches Halten für die Adduktoren.', 'Oberes Bein auf der Bank, Hüfte anheben, in einer geraden Linie halten.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'hip-abduction-machine'), 'de', 'Abduktorenmaschine', 'Maschinentraining für die Abduktoren.', 'Beine auseinanderdrücken, kurz halten, kontrolliert zurückführen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'cable-hip-abduction'), 'de', 'Abduktion am Kabelzug', 'Einbeinige Abduktion am Kabelzug.', 'Fußschlaufe am Bein, das weiter vom Turm entfernt ist, nach außen führen, Oberkörper ruhig halten.');
