INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'tibialis-raise'), 'de', 'Tibialis Raise', 'Fußheben an der Wand oder an der Maschine.', 'Fersen auf dem Boden, Zehen hochziehen, langsam absenken.');
