INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'banded-dorsiflexion'), 'de', 'Fußheben mit Band', 'Bandtraining für den Schienbeinmuskel.', 'Band um den Vorfuß, Fuß zum Schienbein ziehen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'dumbbell-bench-press'), 'de', 'Kurzhantel-Bankdrücken', 'Flachbankdrücken mit Kurzhanteln und größerem Bewegungsumfang als mit der Langhantel.', 'Flach hinlegen, Kurzhanteln auf Brusthöhe absenken, nach oben und leicht zusammen drücken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'machine-chest-press'), 'de', 'Brustpresse', 'Geführtes horizontales Drücken, gut bis nah ans Muskelversagen zu bringen.', 'Griffe auf mittlerer Brusthöhe, nach vorne drücken, kontrolliert zurückführen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'pec-deck'), 'de', 'Butterfly', 'Fliegende an der Maschine für die Brust.', 'Ellbogen leicht gebeugt, Griffe vor der Brust zusammenführen, kontrolliert öffnen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'push-up'), 'de', 'Liegestütz', 'Horizontales Drücken mit dem eigenen Körpergewicht.', 'Hände etwas breiter als schulterbreit, Körper in einer Linie, Brust zum Boden absenken, wieder hochdrücken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'chin-up'), 'de', 'Klimmzug im Untergriff', 'Vertikales Ziehen im Untergriff, mehr Bizeps als im Obergriff.', 'Mit den Handflächen zum Körper hängen, Kinn über die Stange ziehen, vollständig absenken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'assisted-pull-up'), 'de', 'Unterstützter Klimmzug', 'Klimmzug mit Gegengewicht an der Maschine.', 'Knie auf dem Polster, Obergriff, Brust zur Stange ziehen, vollständig absenken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'one-arm-dumbbell-row'), 'de', 'Einarmiges Kurzhantelrudern', 'Einseitiges Rudern mit Abstützen auf der Bank.', 'Hand und Knie auf der Bank, Kurzhantel zur Hüfte ziehen, Oberkörper ruhig halten.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'dumbbell-curl'), 'de', 'Kurzhantelcurl', 'Grundlegender Bizepscurl mit Kurzhanteln.', 'Ellbogen am Körper, hochcurlen und dabei die Handflächen nach oben drehen, kontrolliert absenken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'dip'), 'de', 'Dips', 'Drücken am Barren mit dem eigenen Körpergewicht.', 'Oberkörper recht aufrecht, absenken bis die Oberarme etwa parallel zum Boden sind, wieder hochdrücken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'assisted-dip'), 'de', 'Unterstützte Dips', 'Dips mit Gegengewicht an der Maschine.', 'Knie auf dem Polster, absenken bis die Oberarme etwa parallel zum Boden sind, wieder hochdrücken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'ez-bar-skull-crusher'), 'de', 'SZ-Stirndrücken', 'Trizepsstrecken im Liegen.', 'Flach hinlegen, Stange nur durch Beugen der Ellbogen zur Stirn absenken, wieder strecken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'crunch'), 'de', 'Crunch', 'Grundlegender Crunch am Boden.', 'Auf dem Rücken mit gebeugten Knien liegen, Schultern vom Boden einrollen, langsam absenken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'ab-wheel-rollout'), 'de', 'Bauchroller', 'Anti-Extensionstraining mit dem Bauchroller.', 'Knien, so weit nach vorne rollen, wie der untere Rücken neutral bleibt, zurückrollen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'hack-squat'), 'de', 'Hackenschmidt-Kniebeuge', 'Kniebeuge an der Maschine mit Rückenstütze.', 'Rücken am Polster, Füße schulterbreit, tief beugen, wieder hochdrücken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'goblet-squat'), 'de', 'Goblet Squat', 'Kniebeuge mit einer Kurzhantel vor der Brust.', 'Kurzhantel vor der Brust halten, zwischen die Knie absenken, Oberkörper aufrecht halten.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'walking-lunge'), 'de', 'Gehende Ausfallschritte', 'Abwechselnde Ausfallschritte nach vorne.', 'Kurzhanteln seitlich, nach vorne treten, hinteres Knie Richtung Boden senken, durchtreten.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'treadmill'), 'de', 'Laufband', 'Gehen oder Laufen auf dem Laufband.', 'Geschwindigkeit und Steigung einstellen, Strecke und Zeit eintragen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'rowing-machine'), 'de', 'Rudergerät', 'Ganzkörper-Cardio am Rudergerät.', 'Zuerst mit den Beinen drücken, dann zurücklehnen und den Griff zu den unteren Rippen ziehen, in umgekehrter Reihenfolge zurück.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'stationary-bike'), 'de', 'Fahrradergometer', 'Gelenkschonendes Cardio auf dem Rad.', 'Sattel auf Hüfthöhe, gleichmäßige Trittfrequenz halten, Strecke und Zeit eintragen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'incline-barbell-bench-press'), 'de', 'Schrägbankdrücken', 'Langhanteldrücken auf der Schrägbank für die obere Brust.', 'Bank auf 30 Grad stellen, Stange zur oberen Brust absenken, wieder hochdrücken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'incline-machine-press'), 'de', 'Schrägbankdrücken an der Maschine', 'Geführtes Schrägbankdrücken für die obere Brust.', 'Griffe auf Höhe der oberen Brust, nach oben und vorne drücken, kontrolliert zurückführen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'low-to-high-cable-fly'), 'de', 'Fliegende am Kabelzug von unten', 'Fliegende am Kabelzug mit Zugrichtung nach oben für die obere Brust.', 'Kabel von den unteren Rollen, Ellbogen leicht gebeugt, Griffe auf Kinnhöhe zusammenführen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'dumbbell-fly'), 'de', 'Kurzhantel-Fliegende', 'Fliegende mit freien Gewichten und tiefer Dehnung.', 'Flach hinlegen, Ellbogen leicht gebeugt, Arme in einem weiten Bogen öffnen, Kurzhanteln über der Brust wieder zusammenführen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 't-bar-row'), 'de', 'T-Bar-Rudern', 'Schweres Rudern im neutralen Griff.', 'Aus der Hüfte vorbeugen, Griff zur unteren Brust ziehen, Rücken neutral halten.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'machine-row'), 'de', 'Rudern an der Maschine', 'Geführtes horizontales Ziehen mit Brustauflage.', 'Brust gegen das Polster, Griffe zu den unteren Rippen ziehen, kontrolliert zurückführen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'close-grip-lat-pulldown'), 'de', 'Enges Latziehen', 'Vertikales Ziehen im engen neutralen Griff.', 'V-Griff am Kabel, zur oberen Brust ziehen, Oberkörper fast aufrecht halten.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'single-arm-lat-pulldown'), 'de', 'Einarmiges Latziehen', 'Einseitiges vertikales Ziehen.', 'Einen Griff über Kopf fassen, den Ellbogen seitlich nach unten ziehen, oben den Latissimus dehnen lassen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'machine-shoulder-press'), 'de', 'Schulterpresse', 'Geführtes vertikales Drücken.', 'Griffe auf Schulterhöhe, über Kopf drücken, kontrolliert absenken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'arnold-press'), 'de', 'Arnold Press', 'Kurzhanteldrücken mit Rotation.', 'Mit den Handflächen zum Körper starten, beim Drücken über Kopf nach vorne drehen, beim Absenken umgekehrt.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'machine-lateral-raise'), 'de', 'Seitheben an der Maschine', 'Geführte Isolation für die seitliche Schulter.', 'Polster an den Oberarmen, bis auf Schulterhöhe heben, kontrolliert absenken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'cable-rear-delt-fly'), 'de', 'Reverse Flys am Kabelzug', 'Reverse Flys mit konstanter Spannung am Kabelzug.', 'Kabel auf Schulterhöhe kreuzen, Arme mit leicht gebeugten Ellbogen in einem weiten Bogen öffnen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'ez-bar-curl'), 'de', 'SZ-Curl', 'Bizepscurl mit gewinkeltem Griff, schonender für die Handgelenke.', 'Ellbogen am Körper, hochcurlen, kontrolliert absenken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'cable-curl'), 'de', 'Bizepscurl am Kabelzug', 'Bizepscurl mit konstanter Spannung am Kabelzug.', 'Stange an der unteren Rolle, Ellbogen am Körper, hochcurlen, kontrolliert absenken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'ez-bar-preacher-curl'), 'de', 'SZ-Scottcurl', 'Curl mit freiem Gewicht und auf einem Polster fixierten Oberarmen.', 'Oberarme flach auf dem Polster, hochcurlen, absenken bis die Arme fast gestreckt sind.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'triceps-straight-bar-pushdown'), 'de', 'Trizepsdrücken mit gerader Stange', 'Trizepsdrücken am Kabelzug mit gerader Stange.', 'Obergriff, Ellbogen seitlich fixiert, bis zur Streckung nach unten drücken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'triceps-v-bar-pushdown'), 'de', 'Trizepsdrücken mit V-Griff', 'Trizepsdrücken am Kabelzug mit gewinkeltem V-Griff.', 'Ellbogen seitlich fixiert, bis zur Streckung nach unten drücken, kontrolliert zurückführen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'single-arm-cable-pushdown'), 'de', 'Einarmiges Trizepsdrücken', 'Einseitiges Trizepsdrücken am Kabelzug.', 'Ein Griff, Ellbogen seitlich fixiert, bis zur Streckung nach unten drücken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'overhead-dumbbell-triceps-extension'), 'de', 'Überkopf-Trizepsstrecken mit Kurzhantel', 'Trizepstraining in gedehnter Position mit einer Kurzhantel.', 'Kurzhantel mit beiden Händen über Kopf halten, hinter den Kopf absenken, Ellbogen strecken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'machine-crunch'), 'de', 'Crunch an der Maschine', 'Crunch mit Zusatzgewicht an der Maschine.', 'Polster auf Brusthöhe einstellen, Wirbelsäule nach unten einrollen, langsam zurück.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'hanging-knee-raise'), 'de', 'Hängendes Knieheben', 'Leichtere Variante des hängenden Beinhebens.', 'An der Stange hängen, Knie zur Brust ziehen, ohne Schwung absenken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'decline-sit-up'), 'de', 'Negativ-Sit-up', 'Sit-up auf der Negativbank.', 'Füße fixiert, Oberkörper zu den Knien einrollen, langsam absenken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'front-squat'), 'de', 'Frontkniebeuge', 'Kniebeuge mit der Stange vorne auf den Schultern.', 'Stange auf der vorderen Schulter, Ellbogen hoch, mit aufrechtem Oberkörper tief beugen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'smith-machine-squat'), 'de', 'Kniebeuge an der Multipresse', 'Kniebeuge an der geführten Stange.', 'Stange auf dem oberen Rücken, Füße leicht nach vorne, tief beugen, wieder hochdrücken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'reverse-lunge'), 'de', 'Ausfallschritte rückwärts', 'Ausfallschritt nach hinten, schonender für die Knie.', 'Kurzhanteln seitlich, nach hinten treten, hinteres Knie Richtung Boden senken, zurück in den Stand.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'step-up'), 'de', 'Step-up', 'Einbeiniges Aufsteigen auf eine Box.', 'Kurzhanteln seitlich, auf die Box steigen, über den vorderen Fuß drücken, langsam absenken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'dumbbell-romanian-deadlift'), 'de', 'Rumänisches Kreuzheben mit Kurzhanteln', 'Hüftbeugung mit Kurzhanteln.', 'Hüfte nach hinten schieben, Kurzhanteln nah an den Beinen, am Ende der Dehnung stoppen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'sumo-deadlift'), 'de', 'Sumo-Kreuzheben', 'Kreuzheben vom Boden mit breitem Stand.', 'Breiter Stand, innerhalb der Knie greifen, Rumpf anspannen, den Boden auseinanderdrücken, Hüfte durchstrecken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'nordic-curl'), 'de', 'Nordic Curl', 'Exzentrische Kniebeugung mit dem eigenen Körpergewicht.', 'Knöchel fixiert, Oberkörper so langsam wie möglich nach vorne absenken, mit den Händen wieder hochdrücken.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'glute-bridge'), 'de', 'Beckenheben', 'Hüftstreckung vom Boden.', 'Auf dem Rücken mit gebeugten Knien liegen, Hüfte hochdrücken, oben anspannen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'leg-press-calf-raise'), 'de', 'Wadenheben an der Beinpresse', 'Wadenheben auf der Plattform der Beinpresse.', 'Fußballen an der Plattformkante, Knie fast gestreckt, über die Zehen drücken, unten voll dehnen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'elliptical'), 'de', 'Crosstrainer', 'Gelenkschonendes Cardio auf dem Crosstrainer.', 'Gleichmäßiges Tempo halten, Strecke und Zeit eintragen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'stair-climber'), 'de', 'Treppensteiger', 'Cardio an der Treppenmaschine.', 'Aufrechte Haltung, Hände nur leicht auflegen, Strecke und Zeit eintragen.');
INSERT INTO exercise_translation (exercise_id, locale, name, description, instructions) VALUES ((SELECT id FROM exercise WHERE slug = 'zone-2-treadmill'), 'de', 'Laufband Zone 2', 'Gleichmäßiges Cardio mit niedriger Intensität auf dem Laufband.', 'Ein Tempo wählen, bei dem ein Gespräch noch möglich ist, Strecke und Zeit eintragen.');
INSERT INTO routine_translation (routine_id, locale, name, description) VALUES ((SELECT id FROM routine WHERE slug = 'push'), 'de', 'Push', 'Obere Brust, Brustisolation, Trizeps und seitliche Schulter.');
INSERT INTO routine_translation (routine_id, locale, name, description) VALUES ((SELECT id FROM routine WHERE slug = 'pull'), 'de', 'Pull', 'Latissimus, oberer Rücken und Bizeps.');
INSERT INTO routine_translation (routine_id, locale, name, description) VALUES ((SELECT id FROM routine WHERE slug = 'legs'), 'de', 'Beine', 'Beine an Maschinen, Waden und unterer Rücken.');
INSERT INTO routine_translation (routine_id, locale, name, description) VALUES ((SELECT id FROM routine WHERE slug = 'upper'), 'de', 'Oberkörper', 'Brust, Latissimus, oberer Rücken, Trizeps und Bizeps.');
INSERT INTO routine_translation (routine_id, locale, name, description) VALUES ((SELECT id FROM routine WHERE slug = 'lower'), 'de', 'Unterkörper', 'Beine an Maschinen, Waden, Bauch und unterer Rücken.');
INSERT INTO program_translation (program_id, locale, name, description) VALUES ((SELECT id FROM program WHERE slug = 'push-pull-legs'), 'de', 'Push Pull Beine', 'Drei Trainingstage hintereinander, dann ein Ruhetag.');
INSERT INTO program_translation (program_id, locale, name, description) VALUES ((SELECT id FROM program WHERE slug = 'upper-lower'), 'de', 'Oberkörper Unterkörper', 'Oberkörper, Unterkörper, dann ein Ruhetag.');
